<script setup lang="ts">
/**
 * A Button preset whose face is an Avatar (`design/components/avatar-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useTemplateRef } from 'vue'

import { Icon, agentMember, agentPress } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/avatar-button.module.css'
import Avatar from '../structure/Avatar.vue'

export interface AvatarButtonProps {
  /**
   * Marks the button as the current location with `aria-current="page"`, as Button's `current`
   * does.
   */
  current?: boolean
  disabled?: boolean
  /**
   * The accessible name of the action, such as "Account menu". It is required and it is not the
   * person's name: a face says who, and a button says what a press does.
   */
  label: string
  /**
   * The action has started and not finished. Keeps focus and name, hides the face behind the
   * spinner, and ignores presses.
   */
  loading?: boolean
  /**
   * Avatar's `name`: the initials, and the `user` glyph when it is empty. Never the accessible
   * name.
   */
  name: string
  /**
   * Makes the button a toggle, as Button's `pressed` does: `aria-pressed` mirrors it and
   * `data-state="on|off"` exposes it to CSS. Omitted, the button is not a toggle.
   */
  pressed?: boolean
  /**
   * The face's size, which is Avatar's. The box around it is never smaller than the size's
   * control height.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * Avatar's `src`: the image. A URL that fails to load leaves the initials.
   */
  src?: string
}

defineOptions({ name: 'AvatarButton', inheritAttrs: false })

const props = withDefaults(defineProps<AvatarButtonProps>(), {
  current: false,
  disabled: false,
  loading: false,
  pressed: undefined,
  size: 'md',
})
const emit = defineEmits<{ click: [event: MouseEvent] }>()
const control = useTemplateRef<HTMLElement>('control')
const dataState = computed(() =>
  props.loading
    ? 'loading'
    : props.pressed === undefined
      ? undefined
      : props.pressed
        ? 'on'
        : 'off',
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'AvatarButton',
    element: () => control.value,
    state: () => ({ disabled: props.disabled, loading: props.loading }),
    actions: { press: () => agentPress(control.value) },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <button
    ref="control"
    :class="styles.button"
    type="button"
    :disabled="disabled"
    :aria-label="label"
    :aria-busy="loading ? true : undefined"
    :aria-current="current ? 'page' : undefined"
    :aria-pressed="pressed"
    data-variant="ghost"
    data-tone="neutral"
    :data-size="size"
    :data-state="dataState"
    :data-disabled="disabled ? '' : undefined"
    data-member="avatar-button"
    @click="!loading && emit('click', $event)"
  >
    <!-- face -->
    <span :class="styles.face">
      <Avatar :name="name" :src="src" :size="size" />
    </span>
    <!-- spinner -->
    <span v-if="loading" :class="styles.spinner">
      <Icon name="loading" :size="size" />
    </span>
  </button>
</template>
